#!/bin/bash
E=/workspace/dataset/test6_executable
# q <url> [b] [c]  -- defaults b=Z c=Z
q(){
  b="${2-Z}"; c="${3-Z}"
  printf '=== a=[%s] b=[%s] c=[%s]\n' "$1" "$b" "$c"
  out=$("$E" --a="$1" --b="$b" --c="$c" 2>&1); rc=$?
  printf '%s\n' "$out" | cat -A
  printf 'rc=%s\n' "$rc"
}

